SELECT (SELECT count(*) FROM cursos WHERE codigo LIKE 'DEMO-%') AS cursos,
       (SELECT count(*) FROM unidades_curriculares WHERE codigo LIKE 'DEMO-%') AS ucs,
       (SELECT count(*) FROM turmas WHERE codigo LIKE 'DEMO-%') AS turmas,
